export function checkDatadogField() {
  const site = document.getElementById('site') as HTMLInputElement
  return site?.value.length > 0
}

export function datadogSiteFieldListener(flipEndpointLanguage: () => void) {
  const site = document.getElementById('site') as HTMLInputElement
  const saveButton = document.getElementsByName('store_button')[0] as HTMLButtonElement

  if (site) {
    const startValue = site.value

    site.setAttribute('save', String(saveButton.disabled))
    site.addEventListener('change', () => {
      if (site.value !== startValue) {
        saveButton.disabled = true
        flipEndpointLanguage()
      } else {
        if (site.getAttribute('save') === 'false') {
          saveButton.disabled = false
          flipEndpointLanguage()
        }
      }
    })
  }
}
